import React from 'react';
import TableOfContent from '../../components/TableOfContent';

function 루테늄() {
	return (
		<>
			<div className="px-4" style={{marginTop:40}}>
        <div className="container" id="page">
          <div className="row">
            <div className="col-9" id="left"  >
              <MainContents />
            </div>
            <div className="col-3" id="right" >
              <TableOfContent />
            </div>
          </div>
        </div>
			</div>
		</>
	);
};
export default 루테늄;

function MainContents() {
	const title = 'ruthenium Base Catalyst';

	return (
		<div>
      <h1 className='title' id='c1'>{title}</h1>	
      <hr className='class-1'/>
      <p><b>TMDC와 MXene: 물 분해, CO2RR, NRR 촉매 매력적 이유
        <a href='https://pubs.rsc.org/en/content/articlelanding/2021/ee/d1ee03211a'>(1)</a></b></p>
      <ol>
        <li>이론적 시뮬레이션에 따르면 2D TMDC와 MXene의 불균일한 활성 부위는 기체 분자( 예 : CO 2 및 N 2 )의 화학 흡착 및 수소화에 대한 활성화 에너지 장벽을 낮추어 반응의 느린 동역학과 낮은 선택성을 크게 극복합니다 .18,19 </li>
        <li>TMDC와 MXene의 표면 구조, 전자 상태 및 기계적 특성은 일반적으로 다른 2D 재료보다 조정이 용이하여 다양한 반응을 표적으로 삼고 원치 않는 부반응( 예 : 수소 발생 반응(HER))을 줄입니다. 20,21 구체적으로, TMDC 및 MXene의 전자 구조의 풍부한 조정 가능성은 (1) 수많은 전이 금속 원자와 비전이 금속 원자를 결합하는 능력, (2) 도핑 또는 합금화를 통한 추가 조정 가능성 , (3) 도핑, 변형 등을 통한 상 엔지니어링 에서 비롯됩니다.</li>
        <li>TMDC 및 MXene의 전형적인 전이 금속 원소 W 및 Mo. S 친환경적 화학 전환을 위한 유망한 촉매.</li>
        <li></li>
        <li>표면 활성화, 전하 분리 및 수송, 산화환원 반응을 위한 전자 구조 조작</li>
      </ol>



			<h5 id='c30'>++++ 참고문헌 ++++</h5>
        <ol>
          <li><a href='https://pubs.rsc.org/en/content/articlelanding/2021/ee/d1ee03211a'>2D 전이금속 디칼코게나이드(TMDC) 및 카바이드/질화물(MXene) 촉매를 이용한 이산화탄소 및 질소 환원 반응</a></li>
          <li><a href='https://www.sciencedirect.com/science/article/pii/S1872206724600136?dgcid=rss_sd_all'>A review on fundamentals for designing stable ruthenium-based catalysts for the hydrogen and oxygen evolution reactions</a></li>
          <li><a href='https://www.frontiersin.org/journals/energy-research/articles/10.3389/fenrg.2021.654460/full'>전기 촉매의 Sabatier 원리: 기본, 한계 및 확장</a></li>
          <li><a href=''></a></li>
          <li><a href=''></a></li>
          <li><a href=''></a></li>
        </ol>

    </div>
  )
}
    
