import React from 'react';
import TableOfContent from '../../components/TableOfContent';

function UpConversionR() {
	return (
		<>
			<div className="px-4" style={{marginTop:40}}>
        <div className="container" id="page">
          <div className="row">
            <div className="col-9" id="left"  >
              <MainContents />
            </div>
            <div className="col-3" id="right" >
              <TableOfContent />
            </div>
          </div>
        </div>
			</div>
		</>
	);
};
export default UpConversionR;

function MainContents() {
	const title = '참고 문헌 정리';

	return (
		<div>
			<h1 className='title' id='c0'>{title}</h1>	

			<hr className='class-1'/>
			<h3 id='c1'>광자 상향 변환 Photon Up-Conversion(anti-Stokes emissions)</h3>
			<ol>
				<li><a href="https://www.sciencedirect.com/science/article/pii/S0169433219336566">Nb, Yb, Tm -Visible/near-infrared upconversion nanoparticles/g-C3N4</a></li>
			</ol>

		</div>
	)
}
