import { Outlet } from 'react-router-dom';
import Navbar from './Navbar';
import SideList from './Sidebar';

const BookLayout = () => {
  return (
    <div>

      <div className="nav-area">
        <Navbar />
      </div>

      <div className="row">
        <div className="col-2" style={{backgroundColor:'#5279f8'}}>
          <SideList />
        </div>
        <div className="col-10 content">  {/*style={{background:'green'}} */}
          <Outlet />
        </div>
      </div>

    </div>
  );
};

export default BookLayout;
